<?php require 'includes/functions.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message==='')flash('danger','Please enter your name, a valid email, and your message.');else{$pdo->prepare('INSERT INTO contact_messages(name,email,phone,subject,message) VALUES(?,?,?,?,?)')->execute([$name,$email,trim($_POST['phone']??''),trim($_POST['subject']??''),$message]);flash('success','Thanks — your message has been sent.');}go('contact.php');}$pageTitle='Contact Us';require 'includes/header.php';require 'includes/navbar.php';?><main class="container my-5"><div class="row g-5"><div class="col-lg-5"><p class="tracking text-muted">CONTACT OVERSO</p><h1 class="section-title">We are here to help.</h1><p>Questions about an order, sizing, delivery, or a product? Send us a message.</p><div class="card card-body mt-4"><b>Email</b><p>hello@overso.test</p><b>Phone</b><p>+91 90000 00000</p><b>Address</b><p class="mb-0">OVERSO Studio, 24 Park Street, Kolkata, West Bengal 700016</p></div></div><div class="col-lg-7"><form method="post" class="card card-body"><h2 class="h4 mb-3">Send a message</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" class="form-control" name="email" required></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="col-md-6"><label class="form-label">Subject</label><input class="form-control" name="subject"></div><div class="col-12"><label class="form-label">Message</label><textarea class="form-control" rows="5" name="message" required></textarea></div><div><button class="btn btn-dark">Send message</button></div></div></form></div></div></main><?php require 'includes/footer.php';?>
